    5: 'Plus', 6: 'Dominos', 7: 'Connections', farg: 'Circuit Board', 8: 'Hexagons', 9: 'Brick Wall',
    10: 'X Equals', mi: 'Tic Tac Toe', 11: 'Boxes', fm: 'Overlapping Circles', 12: 'Floating Cogs',
