    extra: { bg: '#D5ECE6', fg: '#409982', opacity: 0.25 },
    hero: { bg: '#9179BA', fg: '#826CA7', opacity: 1 }, // heropatterns.com header
    dark: { bg: '#3D3847', fg: '#9179BA', opacity: 0.22 },
    soft: { bg: '#F0EDF5', fg: '#9C92AC', opacity: 0.22 },
