  const browse = '<path d="M9.293 12.536L5.757 9l1.415-1.414L10 10.414l2.828-2.828L14.243 9 10 13.243l-.707-.707zM20 10c0-5.523-4.477-10-10-10S0 4.477 0 10s4.477 10 10 10 10-4.477 10-10zM10 2c-4.418 0-8 3.582-8 8s3.582 8 8 8 8-3.582 8-8-3.582-8-8-8z" fill="currentColor" fill-rule="evenodd"/>';

  function icon(name, size = 20) {
    if (name === 'browse') return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 20 20" aria-hidden="true">${browse}</svg>`;
    return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="${paths[name]}"/></svg>`;
  }

  // ":-" is Prolog's "if" — the module's mark.
  const mark = (size = 36) => `<svg width="${size}" height="${size}" viewBox="0 0 36 36" aria-hidden="true"><rect width="36" height="36" rx="9" fill="#9179BA"/><circle cx="12" cy="12.5" r="3" fill="#fff"/><circle cx="12" cy="23.5" r="3" fill="#fff"/><rect x="18" y="16.5" width="11" height="3" rx="1.5" fill="#fff"/></svg>`;

  const STATUS = { now: ['b-now', 'In lectures now'], covered: ['b-done', 'Covered'], upcoming: ['b-up', 'Coming up'] };
  const badge = (status, text) => `<span class="badge ${STATUS[status][0]}">${text ?? STATUS[status][1]}</span>`;
