  const tile = (d, cls = '') => `<span class="tile ${cls}" style="${deckStyle(d)}" aria-hidden="true"><span>${tileLabel(d)}</span></span>`;
  const labSlot = () => { const i = P.store.get('labSlot', null); return i == null ? null : LPN.labs.slots[i] ?? null; };
  const plural = (n, word, many = word + 's') => `${n} ${n === 1 ? word : many}`;
  // CC BY 4.0 asks for creator, licence link, and a note that the patterns were changed (we recolour them).
